 // Read-only static audit: code size/IFMA count, never latency or spill causes.
 let exe=p("target-new/release/probe");let nm=Command::new("nm").args(["-S","--size-sort",exe.to_str().unwrap()]).output().unwrap();assert!(nm.status.success());let mut code=Vec::new();for line in String::from_utf8(nm.stdout).unwrap().lines(){let t:Vec<_>=line.split_whitespace().collect();if t.len()!=4||!t[3].contains("probe6kernel")||!t[3].contains("8FqConfig"){continue}let name=t[3];let output=Command::new("objdump").args(["-d","--no-show-raw-insn",&format!("--disassemble={name}"),exe.to_str().unwrap()]).output().unwrap();assert!(output.status.success());let text=String::from_utf8(output.stdout).unwrap();let ins:Vec<_>=text.lines().filter(|l|l.split_once(':').map(|(a,_)|a.trim().chars().all(|c|c.is_ascii_hexdigit())&&!a.trim().is_empty()).unwrap_or(false)).collect();let new=name.contains("Kb1_");let kind=if name.contains("Kh0_"){0}else if name.contains("Kh1_"){1}else if name.contains("Kh2_"){2}else{panic!()};fs::write(p(&format!("assembly-fq-{kind}-{new}.txt")),&text).unwrap();code.push(json!({"new":new,"kind":kind,"symbol":name,"bytes":usize::from_str_radix(t[1],16).unwrap(),"instruction_sites":ins.len(),"IFMA_sites":ins.iter().filter(|l|l.contains("vpmadd52")).count(),"disassembly_sha256":h(text.as_bytes())}));}assert_eq!(code.len(),6);
