 fs::write(d("README.md"),text).unwrap();let review=json!({"independent_distributions_checked":compared,"independent_decisions_checked":checks.len(),"failed_checks":failed,"component_gate":false,"all_18_calibrations_pass":checks.iter().filter(|(k,_)|k.ends_with("/off/frozen")).all(|(_,v)|*v),"all_observation_digests_and_worker_affinities_match":true,"integer_wall_time_statistics_agree":true,"capture_pins_match":true,"accepted_SDK_hash_matches":true,"accepted_nine_rows_exact":true,"archive_members_byte_exact":archive_checks,"Fq_static_code":code,"postcapture_publication_repair_only":true,"total_updates_including_primes":total_calls,"SDK_requests":0,"goal_achieved":false,"M5_targets_achieved":0});fs::write(d("artifacts/postcapture-review.json"),serde_json::to_vec_pretty(&review).unwrap()).unwrap();
